/**
 * Error type crossing the UniFFI boundary from `DocumentCore`.
 */
sealed class DocumentCoreException: kotlin.Exception() {
    
    class ConfigurationException(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class FileBrokerFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class PasswordRequired(
        ) : DocumentCoreException() {
        override val message
            get() = ""
    }
    
    class InvalidPdf(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class SessionNotFound(
        
        val `sessionId`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "sessionId=${ `sessionId` }"
    }
    
    class DocumentNotLocallyWritable(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    /**
     * The redaction could not be carried out (`REDACT-001`).
     */
    class RedactionFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    /**
     * The redaction was carried out, but it could not be verified in every
     * respect (`REDACT-002`). The document must not be presented as
     * redacted.
     */
    class RedactionUnverified(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    /**
     * The redaction failed and the document could **not** be put back
     * (`REDACT-002`).
     *
     * The session holds a document in an unknown state. The shell has to
     * tell the user that the document has to be opened again — the file on
     * the disk still holds the original.
     */
    class RedactionRollbackFailed(
        
        val `original`: kotlin.String, 
        
        val `rollback`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "original=${ `original` }, rollback=${ `rollback` }"
    }
    
    /**
     * A comment of the reviewer was refused (`ANNOT-001`).
     *
     * The note has no text, no area, or a key that the rail of the
     * profession does not carry. The document is untouched.
     */
    class CommentRefused(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class NavigationFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class TransactionFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class SaveFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class RecoveryFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class OperationBlockedBySignature(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class ImagingFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class InternalFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DocumentCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): DocumentCoreException = FfiConverterTypeDocumentCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDocumentCoreError : FfiConverterRustBuffer<DocumentCoreException> {
    override fun read(buf: ByteBuffer): DocumentCoreException {
        

        return when(buf.getInt()) {
            1 -> DocumentCoreException.ConfigurationException(
                FfiConverterString.read(buf),
                )
            2 -> DocumentCoreException.FileBrokerFailure(
                FfiConverterString.read(buf),
                )
            3 -> DocumentCoreException.PasswordRequired()
            4 -> DocumentCoreException.InvalidPdf(
                FfiConverterString.read(buf),
                )
            5 -> DocumentCoreException.SessionNotFound(
                FfiConverterString.read(buf),
                )
            6 -> DocumentCoreException.DocumentNotLocallyWritable(
                FfiConverterString.read(buf),
                )
            7 -> DocumentCoreException.RedactionFailure(
                FfiConverterString.read(buf),
                )
            8 -> DocumentCoreException.RedactionUnverified(
                FfiConverterString.read(buf),
                )
            9 -> DocumentCoreException.RedactionRollbackFailed(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> DocumentCoreException.CommentRefused(
                FfiConverterString.read(buf),
                )
            11 -> DocumentCoreException.NavigationFailure(
                FfiConverterString.read(buf),
                )
            12 -> DocumentCoreException.TransactionFailure(
                FfiConverterString.read(buf),
                )
            13 -> DocumentCoreException.SaveFailure(
                FfiConverterString.read(buf),
                )
            14 -> DocumentCoreException.RecoveryFailure(
                FfiConverterString.read(buf),
                )
            15 -> DocumentCoreException.OperationBlockedBySignature(
                FfiConverterString.read(buf),
                )
            16 -> DocumentCoreException.ImagingFailure(
                FfiConverterString.read(buf),
                )
            17 -> DocumentCoreException.InternalFailure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DocumentCoreException): ULong {
        return when(value) {
            is DocumentCoreException.ConfigurationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.FileBrokerFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
