                FfiConverterTypeFfiSaveSuccessSnapshot.read(buf),
                )
            2 -> FfiSaveOutcome.Conflict(
                FfiConverterTypeFfiSaveConflict.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
