            }
            is FfiSaveOutcome.Conflict -> {
                buf.putInt(2)
                FfiConverterTypeFfiSaveConflict.write(value.`conflict`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





